begin read only;
select set_config('alignment.test_list', (select id::text from public.user_lists order by created_at limit 1), true);
select set_config('alignment.test_owner', (select user_id::text from public.user_lists where id::text = current_setting('alignment.test_list')), true);
select set_config('alignment.public_count', (select count(*)::text from public.user_lists where visibility = 'public'), true);
select set_config('request.jwt.claim.sub', current_setting('alignment.test_owner'), true);
select set_config('request.jwt.claims', jsonb_build_object('sub',current_setting('alignment.test_owner'),'role','authenticated')::text, true);
set local role authenticated;
select 1 / case when current_user = 'authenticated' and exists(select 1 from public.user_lists where id::text = current_setting('alignment.test_list')) then 1 else 0 end as owner_read_check;
reset role;
select set_config('request.jwt.claim.sub', gen_random_uuid()::text, true);
select set_config('request.jwt.claims', jsonb_build_object('sub',current_setting('request.jwt.claim.sub'),'role','authenticated')::text, true);
set local role authenticated;
select 1 / case when not exists(select 1 from public.user_lists where visibility <> 'public' and user_id <> auth.uid()) and (select count(*) from public.user_lists where visibility = 'public') = current_setting('alignment.public_count')::bigint then 1 else 0 end as other_user_visibility_check;
reset role;
select set_config('request.jwt.claim.sub', '', true);
select set_config('request.jwt.claims', '{"role":"anon"}', true);
set local role anon;
select 1 / case when current_user = 'anon' and not exists(select 1 from public.user_lists where visibility <> 'public') and not exists(select 1 from public.list_templates where visibility <> 'public') and (select count(*) from public.user_lists) = current_setting('alignment.public_count')::bigint then 1 else 0 end as visitor_visibility_check;
reset role;
select 1 / case when (select count(*) from pg_class where oid in ('public.list_templates'::regclass,'public.user_lists'::regclass) and relrowsecurity) = 2 and exists(select 1 from pg_constraint where conrelid='public.user_lists'::regclass and conname='user_lists_template_id_fkey' and pg_get_constraintdef(oid) like '%ON DELETE SET NULL%') then 1 else 0 end as rls_and_snapshot_fk_check;
rollback;
select 'Read-only owner, other-user and visitor RLS assertions passed; RLS and snapshot foreign key preserved.' as result;
